"""Markdown evaluation report. No timestamps, so the same inputs give the same file."""

from __future__ import annotations

from invoice_agent.evals.metrics import (
    EXTRACTION_THRESHOLD,
    GUARDRAIL_THRESHOLDS,
    PRECISION_THRESHOLD,
    RECALL_THRESHOLDS,
    RETRIEVAL_THRESHOLD,
    DetectionReport,
    ExtractionReport,
    guardrail_pass_rate,
)

DISCLAIMER = (
    "All data is synthetic and generated by rules (seeded). These numbers are a reproducible "
    "test bench, not real-world performance."
)


def pct(value: float | None) -> str:
    return "n/a" if value is None else f"{value * 100:.1f}%"


def verdict(value: float | None, threshold: float) -> str:
    if value is None:
        return "not measured"
    return "pass" if value >= threshold else "**FAIL**"


def extraction_section(name: str, r: ExtractionReport) -> list[str]:
    out = [
        f"### Extraction: {name}",
        "",
        (
            f"Key-field accuracy: **{pct(r.key_field_accuracy)}** "
            f"(threshold {pct(EXTRACTION_THRESHOLD)}: {verdict(r.key_field_accuracy, EXTRACTION_THRESHOLD)})"
        ),
        "",
        "| Field | Correct | Total | Accuracy |",
        "|---|---|---|---|",
    ]
    for field, score in r.fields.items():
        out.append(f"| {field} | {score.correct} | {score.total} | {pct(score.accuracy)} |")
    out += [
        "",
        f"- Readable documents sent to manual review: {r.manual_review} of {r.readable_documents}",
        f"- Unreadable PDFs sent to manual review: {r.unreadable_caught} of {r.unreadable_total}",
        f"- Confident but wrong (passed the self-check with a wrong key field): "
        f"{len(r.confident_but_wrong)}"
        + (f" ({', '.join(r.confident_but_wrong)})" if r.confident_but_wrong else ""),
        (
            f"- Lines mapped to the right catalog product: {r.product_mapping.correct} of "
            f"{r.product_mapping.total} ({pct(r.product_mapping.accuracy)})"
        ),
        "",
    ]
    return out


def difficulty_section(rows: list[tuple[str, str, ExtractionReport]]) -> list[str]:
    """One row per (difficulty, extractor) on the hard split."""
    out = [
        "### Hard split by difficulty",
        "",
        (
            "| Difficulty | Extractor | Documents | Key-field accuracy | Sent to review "
            "| Product mapping |"
        ),
        "|---|---|---|---|---|---|",
    ]
    for difficulty, extractor, r in rows:
        out.append(
            f"| {difficulty} | {extractor} | {r.readable_documents} | {pct(r.key_field_accuracy)} "
            f"| {r.manual_review} | {pct(r.product_mapping.accuracy)} |"
        )
    return [*out, ""]


def detection_section(name: str, r: DetectionReport) -> list[str]:
    out = [
        f"### Anomaly detection: {name}",
        "",
        "| Type | TP | FP | FN | Precision | Recall | Recall threshold |",
        "|---|---|---|---|---|---|---|",
    ]
    for type_, s in r.per_type.items():
        threshold = RECALL_THRESHOLDS[type_]
        out.append(
            f"| {type_} | {s.true_positives} | {s.false_positives} | {s.false_negatives} "
            f"| {pct(s.precision)} | {pct(s.recall)} | {pct(threshold)}: {verdict(s.recall, threshold)} |"
        )
    total = r.overall
    out += [
        (
            f"| **all** | {total.true_positives} | {total.false_positives} | {total.false_negatives} "
            f"| {pct(total.precision)} | {pct(total.recall)} | precision {pct(PRECISION_THRESHOLD)}: "
            f"{verdict(total.precision, PRECISION_THRESHOLD)} |"
        ),
        "",
        f"- Trap cases wrongly flagged: {len(r.trap_false_alarms)}"
        + (f" ({', '.join(r.trap_false_alarms)})" if r.trap_false_alarms else ""),
        f"- Missed: {', '.join(f'{i} {t}' for i, t in r.missed) or 'none'}",
        f"- False flags: {', '.join(f'{i} {t}' for i, t in r.false_flags) or 'none'}",
        "",
    ]
    return out


def agent_section(name: str, reviews) -> list[str]:
    """How the agent behaved: calls, limits, cost, and what its contributions were worth."""
    runs = [r.run for r in reviews if r.run is not None]
    stopped: dict[str, int] = {}
    for run in runs:
        stopped[run.stopped_reason] = stopped.get(run.stopped_reason, 0) + 1
    n = len(runs) or 1
    flags = [f for r in reviews for f in r.flags]
    quoted = [f for f in flags if f.type != "wrong_vat"]
    return [
        f"### Agent behaviour: {name}",
        "",
        f"- Invoices: {len(reviews)}; agent called on {len(runs)} (the others needed no model)",
        f"- Stopped: {', '.join(f'{k} {v}' for k, v in sorted(stopped.items())) or 'n/a'}",
        (
            f"- Mean per call: {sum(r.steps for r in runs) / n:.1f} steps, "
            f"{sum(r.input_tokens for r in runs) / n:.0f} input and "
            f"{sum(r.output_tokens for r in runs) / n:.0f} output tokens, "
            f"${sum(r.cost_usd for r in runs) / n:.4f}, {sum(r.seconds for r in runs) / n:.1f} s"
        ),
        f"- Lines matched to the catalog by the agent: {sum(len(r.agent_mapping) for r in reviews)}",
        (
            f"- Agent quotes verified / rejected: {sum(r.citations_verified for r in reviews)} / "
            f"{sum(r.citations_rejected for r in reviews)}; flags with a verified clause quote: "
            f"{sum(1 for f in quoted if f.quote)} of {len(quoted)}"
        ),
        (
            f"- Agent findings ignored (not produced by the checks): "
            f"{sum(r.findings_ignored for r in reviews)}"
        ),
        f"- Sent to manual review: {sum(1 for r in reviews if r.status == 'manual_review')}",
        "",
    ]


def guardrail_section(results) -> list[str]:
    rates = guardrail_pass_rate(results)
    out = [
        "## Guardrails (SPEC section 5)",
        "",
        "| Severity | Cases | Held | Pass rate | Threshold |",
        "|---|---|---|---|---|",
    ]
    for severity, threshold in GUARDRAIL_THRESHOLDS.items():
        group = [r for r in results if r.severity == severity]
        out.append(
            f"| {severity} | {len(group)} | {sum(r.blocked for r in group)} "
            f"| {pct(rates[severity])} | {pct(threshold)}: "
            f"{verdict(rates[severity], threshold)} |"
        )
    failed = [r.case_id for r in results if not r.blocked]
    out += [
        "",
        f"- Cases: {', '.join(r.case_id for r in results)}",
        f"- Failed: {', '.join(failed) or 'none'}",
        (
            "- Offline, with a scripted model: these test the structure around the model, not "
            "the model's own judgement. Live adversarial runs are task 10."
        ),
        "",
    ]
    return out


def retrieval_section(scores) -> list[str]:
    out = [
        "## Clause retrieval (BM25)",
        "",
        (
            "| Query set | Supplier filter | Synonyms | Queries | hit@1 | hit@3 | Right topic in top 3 "
            "| hit@3 threshold |"
        ),
        "|---|---|---|---|---|---|---|---|",
    ]
    for s in scores:
        out.append(
            f"| {s.query_set} | {'yes' if s.supplier_filter else 'no'} "
            f"| {'yes' if s.synonyms else 'no'} | {s.queries} | {pct(s.hit_at_1)} "
            f"| {pct(s.hit_at_3)} | {pct(s.right_topic_at_3)} "
            f"| {pct(RETRIEVAL_THRESHOLD)}: {verdict(s.hit_at_3, RETRIEVAL_THRESHOLD)} |"
        )
    out += [
        "",
        (
            "- Without the supplier filter, retrieval finds the right kind of clause but often from "
            "another supplier: the six contracts use near-identical wording. The filter is required."
        ),
        (
            "- The synonym list was written while looking at these contracts, so the 'synonyms: yes' "
            "rows are optimistic; real contracts would need the list grown from their own wording."
        ),
        (
            "- Chance level with the filter: 3 of a supplier's 8 clauses picked at random give hit@3 "
            "37.5%. The queries and questions were also written by the developer who wrote the "
            "contracts; real reviewer questions would be harder."
        ),
        "",
    ]
    return out


def render_report(
    title: str, dataset_summary: dict, sections: list[list[str]], notes: list[str]
) -> str:
    out = [f"# {title}", "", f"> {DISCLAIMER}", "", "## Dataset", ""]
    out += [f"- {key}: {value}" for key, value in dataset_summary.items()]
    out += ["", "## Results", ""]
    for section in sections:
        out += section
    out += [
        "## Not measured yet",
        "",
        "- Cost and time per invoice: shown in the agent sections once live runs are cached.",
        "",
        "## Notes",
        "",
    ]
    out += [f"- {note}" for note in notes]
    return "\n".join(out) + "\n"
